rd"></div><div class="col-md-6"><label class="form-label" for="contrasena_confirmacion">Confirmar contraseña</label><input class="form-control" id="contrasena_confirmacion" name="contrasena_confirmacion" type="password" minlength="8" maxlength="72" autocomplete="new-password"></div></div><div class="form-text">La contraseña se procesa con password_hash() y nunca se presenta en pantalla.</div></fieldset><div class="patient-form-actions"><a class="btn btn-outline-secondary" href="<?= $editing?'/usuarios/detalle?id='.$escape($id):'/usuarios' ?>">Cancelar</a><button class="btn btn-clinic" type="submit">Guardar</button></div></form>
